			written = { ["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "/sit by Raan's campfire until you get Boosted Rest", ["Al'Aketh Stormchasers and Footsoldiers camp just north of {npc:257944} and drop the heirloom; the Shrieklings west of her drop the feathers and talons; the {item:265105} grows along the stream west of her."] = "Al'Aketh Stormchasers and Footsoldiers camp just north of Elegael and drop the heirloom; the Shrieklings west of her drop the feathers and talons; the Lady's Tear Moss grows along the stream west of her.", ["Each of Quel'ana's quests hands you a {item:15908}: use it on the beast she names, then bring the rod back to her in {area:16638}. Windsong Crawlers line the shore west of town; Vuldren Alphas and Ornery Galestriders roam the {area:16626} around the Windfield farm. Her sister {npc:254411} stands beside her."] = "Each of Quel'ana's quests hands you a Taming Rod: use it on the beast she names, then bring the rod back to her in Valanaar. Windsong Crawlers line the shore west of town; Vuldren Alphas and Ornery Galestriders roam the Gustberry Lowlands around the Windfield farm. Her sister Quel'dora stands beside her.", ["Fight north to the {area:16629}. Guardians, Spiritcallers and Blademasters hold the approach; {npc:253576} waits at the shrine's door, {npc:253590} inside the inner sanctum."] = "Fight north to the Shrine of Akir. Guardians, Spiritcallers and Blademasters hold the approach; Hyusaa Quickbreeze waits at the shrine's door, Valennia inside the inner sanctum.", ["Jump off the top of the watchtower and use {spell:1259416} to float down to {npc:251361}, west of the tower."] = "Jump off the top of the watchtower and use Walk on Air to float down to Rorian, west of the tower.", ["Listen to {npc:257554}"] = "Listen to Halaan", ["Rally Valennia, {npc:251968} (west of town) and {npc:252475}"] = "Rally Valennia, Ayessa Dawnsinger (west of town) and Elaadrin", ["The Raw Windstones glitter on the ground just south of the grove. {quest:92463} hovers over the meadow further east, on the way to {npc:249363}."] = "The Raw Windstones glitter on the ground just south of the grove. The Cirrusfly Queen hovers over the meadow further east, on the way to Yala.", ["{npc:251361}: {quest:92485}"] = "Rorian: A Student of Nature", ["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "Xyton Silverwind, the druid trainer, on the ground floor of the tree behind Rorian", ["{npc:252800} again"] = "Aamelia again", ["{npc:254151}, {npc:258130} and {npc:258134} are north-east of {npc:257944}; {npc:253622} stands east of them. Haalien also drops a {quest:94490}. For {quest:94489}, enter the Nightfang Den, heal 7 injured druids and find {npc:258130}."] = "Vayn Moongaze, Jorel Windsinger and Naaleos Leafwhisper are north-east of Elegael; Commander Haalien stands east of them. Haalien also drops a Ripped Missive. For The Wounds of Betrayal, enter the Nightfang Den, heal 7 injured druids and find Jorel.", ["{npc:254589} lurks in the hills south-west of the village, on the way back. {npc:254589} is elite: grouping up is advised."] = "Vulgara lurks in the hills south-west of the village, on the way back. Vulgara the Insatiable is elite: grouping up is advised.", ["{npc:257554} and {npc:263113} stand at the top of the watchtower, a few steps north-east of {npc:251368}."] = "Halaan Hawk-Eye and Myriaal Mistwake stand at the top of the watchtower, a few steps north-east of Elatrell.", ["{npc:257944} again"] = "Elegael again", ["{npc:259084} stands beside the Skyborne Portal where the zeppelin lands. The portal takes you to {zone:1453}."] = "Denaaris stands beside the Skyborne Portal where the zeppelin lands. The portal takes you to Stormwind.", ["{npc:270459}, beside {npc:259084}: for {npc:5504} in {zone:1453}"] = "Alfina Nightgaze, beside Denaaris: for Sheldras Moontree in Stormwind", ["{quest:93159} lives west of {npc:257944}. The Zephyrseed Cones lie in the woods between his hut and {npc:257944}."] = "The Strange Hermit lives west of Elegael. The Zephyrseed Cones lie in the woods between his hut and Elegael." },
